INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/365270','{"collected_at":"2026-10-22T00:01:15.671788+00:00","company":"넷플릭스(Netflix)","deadline":"","description":"• Build successful 360 marketing campaigns for Netflix''s titles (Series, Film & Unscripted) — from strategy development to tactical execution (including media buy, activation, and creative assets) • Drive successful marketing campaigns in Korea while developing export-focused strategies and creative assets designed to resonate with audiences beyond Korea • Leverage audience insights, cultural trends, and campaign performance data to inform marketing strategies and optimize campaigns • Identify culturally relevant opportunities and develop breakthrough ideas that drive conversation and fandom • Support the creation of marketing assets for titles — including creative development, planning, and execution of shoots (key art, AV, etc) • Act as a liaison to internal cross-functional teams at every step of the campaign, from early strategy through campaign completion • Be the main point of contact with agencies — brief, hire, manage, and provide feedback to create best-in-class campaigns • Communicate and collaborate with external studios, showrunners, producers, talent, and talent representatives where needed 마케팅·광고, 브랜드 마케터, 마케팅 전략 기획자, 콘텐츠 마케터","employment_type":"regular","experience":"경력 12년+ / 정규직","keyword":"문화","link":"https://www.wanted.co.kr/wd/365270","location":"한국 서울 종로구 서울특별시 종로구 우정국로 26 (견지동, 센트로폴리스 A동 20층)","matched_keywords":["문화"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=%EB%AC%B8%ED%99%94&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"Marketing Manager, Korea Title Marketing [경력 12년+ / 정규직]"}','b35be1d927701b0ef804cbbabaa7e20357038fc4165f205f35d4246f939a1ad8','2026-10-17T17:35:26+00:00','2026-10-22T00:01:39+00:00','2026-10-17T17:35:26+00:00');
