INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/390231','{"collected_at":"2026-10-27T00:00:42.344209+00:00","company":"리빌더에이아이(리빌더AI)","deadline":"","description":"채용 및 온보딩 • AI/ML 연구, 개발, 기획, 디자인 등 직군별 채용 전략 수립 및 전 과정 운영 (공고 작성, 소싱, 서류·면접 조율, 처우 협의) • 채용 채널 운영 및 채용 브랜딩, 레퍼럴 제도 활성화 • 입사 온보딩 프로그램 설계 및 운영, 수습 기간 관리 평가·보상 및 인사 제도 • 평가 체계(목표 설정, 피드백, 성과 평가) 설계 및 운영 • 연봉·보상 체계 및 스톡옵션 운영 지원 • 직무·등급·호칭 체계 등 조직 규모 확대에 맞춘 인사 제도 설계와 개선 노무 및 인사 운영 • 근태·연차·휴직 등 근로 관리 및 취업규칙·인사 규정 정비 • 근로계약, 급여, 4대보험 등 인사 행정 운영 및 노무사 등 외부 전문가 협업 • 노동법 및 정책 변경에 따른 사내 제도 점검과 대응 조직문화 및 구성원 경험 • 구성원 만족도·몰입도 조사 및 개선 과제 도출 • 타운홀 미팅, 팀 활동, 복지 제도 등 조직문화 프로그램 기획 및 운영 • 구성원 면담과 이슈 대응, 갈등 조정 및 퇴직 프로세스 관리 • 이외 운영관리 부수 업무 HR 데이터 및 프로세스 개선 • 인원·채용·이직 등 HR 지표 관리 및 경영진 보고 • HR 업무 프로세스와 협업 규칙 정착, 관련 툴(HR 시스템, Notion 등) 도입 및 운영 HR, 인사담당","employment_type":"regular","experience":"경력 1년+ / 정규직","keyword":"HR","link":"https://www.wanted.co.kr/wd/390231","location":"한국 경기 성남시 경기도 성남시 분당구 정자일로 95, 4층","matched_keywords":["HR","인사"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=HR&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"HR 매니저 [경력 1년+ / 정규직]"}','eaa3d9daa4266c339f9f0c343d82f9ef3f070d570e5d4d2f37194aad6a7f6080','2026-10-17T17:35:26+00:00','2026-10-27T00:01:28+00:00','2026-10-17T17:35:26+00:00');
